"""Mantle implementation of :class:`A2AEngineAdapter`.

The card comes from the skill catalog. ``include_default_skills`` is a
constructor argument, the same way CALM keeps ``include_conversation_repair``
on its adapter. Task state, the status payload, and cancel are live. Memory
prefill is still a later ticket: inbound text, including a ``set:`` button
tap, is passed through so the existing set-memory path can write it. Caller
metadata is not forwarded until that prefill validates the fields.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import AgentSkill, Message

from rasa.core.a2a_server.config import (
    A2AServerSettings,
    validate_a2a_server_session_config_or_raise,
)
from rasa.core.a2a_server.engine_adapter import EngineCancelResult, PreparedA2AInput
from rasa.core.a2a_server.task_state_mapper import TaskStateMappingResult
from rasa.mantle.a2a.cancel import MantleCancelHandler
from rasa.mantle.a2a.card_source import SkillCatalogCardSource
from rasa.mantle.a2a.status_payload import MantleStatusPayloadBuilder
from rasa.mantle.a2a.task_state import MantleTaskStateMapper
from rasa.mantle.skills.catalog import SkillCatalog
from rasa.shared.engine_version import MANTLE_ENGINE_VERSION
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from a2a.types import Message as A2AMessage

    from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
    from rasa.core.agent import Agent
    from rasa.core.processor import MessageProcessor
    from rasa.shared.core.trackers import DialogueStateTracker


class MantleA2AEngineAdapter:
    """Mantle side of the A2A port.

    Startup validation, the skill-catalog card, task state, the status
    payload, and cancel are live. Memory prefill is not: ``prepare_input``
    keeps the message text so a ``set:`` tap still reaches the set-memory
    path, and drops caller metadata until prefill validates those fields.
    """

    def __init__(
        self,
        agent: "Agent | None" = None,
        *,
        include_default_skills: bool = False,
    ) -> None:
        """Bind a loaded Mantle agent and its card option."""
        self._agent = agent
        self.include_default_skills = include_default_skills

    async def get_card_skills(self) -> list[AgentSkill]:
        """Advertise routable catalog skills; defaults only when the flag is on."""
        catalog = self._skill_catalog()
        if catalog is None:
            raise RasaException(
                "Cannot build A2A card skills: the Mantle agent model is not loaded."
            )
        return SkillCatalogCardSource(
            catalog, include_default_skills=self.include_default_skills
        ).skills()

    def pattern_replies_are_user_facing(self) -> bool:
        """Mantle has no repair patterns, so replies are not split out."""
        return True

    def _skill_catalog(self) -> "SkillCatalog | None":
        agent = self._agent
        processor = agent.processor if agent is not None else None
        static_data = getattr(processor, "mantle_static_data", None)
        if static_data is None:
            return None
        return static_data.skill_catalog

    def prepare_input(
        self,
        message: "A2AMessage | None",
        text: str,
        metadata: dict[str, Any],
    ) -> PreparedA2AInput:
        """Pass text through until memory prefill lands.

        A ``set:`` button tap stays on the message text so
        ``apply_inbound_set_memory_button_tap`` can write it. Caller metadata
        is dropped: a ``seed: true`` project field would otherwise be written
        from unvalidated JSON-RPC metadata. Prefill will sit beside the text
        path and must not replace it.
        """
        # TODO(ENG-3486): read memory prefill beside the set-memory button path.
        del message, metadata
        return PreparedA2AInput(text=text, metadata={})

    def map_task_state(
        self,
        tracker: "DialogueStateTracker",
        *,
        outcome: Any | None = None,
        orchestrator_cancel: bool = False,
    ) -> TaskStateMappingResult:
        """Map the Mantle tracker and recorded turn result to an A2A state."""
        return MantleTaskStateMapper(
            self._catalog_or_empty(),
            include_default_skills=self.include_default_skills,
        ).map(
            tracker,
            outcome=outcome,
            orchestrator_cancel=orchestrator_cancel,
        )

    def uses_latest_action_for_turn_end(self) -> bool:
        """Mantle never closes a turn from ``latest_action_name``."""
        return False

    async def build_status_data(
        self,
        mapping: TaskStateMappingResult,
        tracker: "DialogueStateTracker | None",
        *,
        updater: TaskUpdater,
        user_visible_text: str | None = None,
        conversation_repair_agent_utterances: list[str] | None = None,
    ) -> Message | None:
        """Build the Mantle status payload. Repair utterances are not used."""
        del conversation_repair_agent_utterances
        return MantleStatusPayloadBuilder(
            self._catalog_or_empty(),
            include_default_skills=self.include_default_skills,
        ).build(
            mapping,
            tracker,
            updater=updater,
            user_visible_text=user_visible_text,
        )

    async def cancel_active_work(
        self,
        sender_id: str,
        output_channel: "A2AOutputChannel",
    ) -> EngineCancelResult:
        """Drop the user-facing skill, then publish ``canceled`` with its id."""
        if self._agent is None:
            result = EngineCancelResult()
            await output_channel.publish_terminal_canceled(result)
            return result
        return await MantleCancelHandler.run(
            self._agent,
            sender_id,
            output_channel,
            include_default_skills=self.include_default_skills,
        )

    def _catalog_or_empty(self) -> SkillCatalog:
        catalog = self._skill_catalog()
        if catalog is None:
            return SkillCatalog()
        return catalog

    def validate_startup(
        self,
        settings: A2AServerSettings,
        processor: "MessageProcessor",
    ) -> None:
        """Require ``agent.yml`` to resume an A2A context."""
        validate_a2a_server_session_config_or_raise(
            settings,
            processor.session_config,
            engine_version=MANTLE_ENGINE_VERSION,
        )
